-- Migration 0002: People (students, guardians, staff)
-- Project: Bright Future Academy (BFA) school platform
-- Run once, after migration 0001.
-- Everything runs in one transaction: if any statement fails, nothing is applied.
-- Note: staff_assignments is created in migration 0003 because it
-- references school sections, which do not exist yet.

begin;

-- ---------------------------------------------------------------
-- students
-- Student logins are optional (profile_id can stay empty, decision D2).
-- Admission numbers (BFA/26/0001) are generated by the backend; the
-- database only guarantees they are unique and not blank.
-- home_address_enc holds application-level encrypted text (Phase 3).
-- ---------------------------------------------------------------
create table public.students (
  id                 uuid primary key default gen_random_uuid(),
  profile_id         uuid unique references public.profiles (id) on delete restrict,
  campus_id          uuid not null references public.campuses (id) on delete restrict,
  admission_number   text not null unique
                     check (length(trim(admission_number)) > 0),
  first_name         text not null check (length(trim(first_name)) > 0),
  middle_name        text,
  last_name          text not null check (length(trim(last_name)) > 0),
  gender             text check (gender in ('female', 'male')),
  date_of_birth      date,
  nationality        text,
  state_of_origin    text,
  home_address_enc   text,
  photo_path         text,
  status             text not null default 'active'
                     check (status in ('active', 'withdrawn', 'transferred', 'graduated', 'archived')),
  status_reason      text,
  admitted_on        date,
  left_on            date,
  created_by         uuid references public.profiles (id) on delete set null,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  constraint students_dates_check
    check (left_on is null or admitted_on is null or left_on >= admitted_on)
);

create index students_campus_id_idx on public.students (campus_id);
create index students_status_idx on public.students (status);
create index students_name_idx
  on public.students (lower(last_name), lower(first_name));

-- ---------------------------------------------------------------
-- guardians (parents and other guardians)
-- profile_id stays empty until the guardian's login is created.
-- ---------------------------------------------------------------
create table public.guardians (
  id                 uuid primary key default gen_random_uuid(),
  profile_id         uuid unique references public.profiles (id) on delete restrict,
  first_name         text not null check (length(trim(first_name)) > 0),
  last_name          text not null check (length(trim(last_name)) > 0),
  phone              text,
  whatsapp_number    text,
  email              text
                     check (email is null or email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  occupation         text,
  home_address_enc   text,
  status             text not null default 'active'
                     check (status in ('active', 'inactive')),
  created_by         uuid references public.profiles (id) on delete set null,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

create unique index guardians_email_unique
  on public.guardians (lower(email)) where email is not null;
create index guardians_phone_idx on public.guardians (phone);
create index guardians_name_idx
  on public.guardians (lower(last_name), lower(first_name));

-- ---------------------------------------------------------------
-- guardian_student_links
-- A parent can see a child's records only while status = 'verified'.
-- ---------------------------------------------------------------
create table public.guardian_student_links (
  id                  uuid primary key default gen_random_uuid(),
  guardian_id         uuid not null references public.guardians (id) on delete restrict,
  student_id          uuid not null references public.students (id) on delete restrict,
  relationship        text not null
                      check (relationship in ('mother', 'father', 'guardian', 'grandparent', 'sibling', 'other')),
  is_primary          boolean not null default false,
  status              text not null default 'pending'
                      check (status in ('pending', 'verified', 'revoked')),
  verified_by         uuid references public.profiles (id) on delete restrict,
  verified_at         timestamptz,
  verification_note   text,
  revoked_at          timestamptz,
  revoked_reason      text,
  created_by          uuid references public.profiles (id) on delete set null,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint guardian_student_links_unique unique (guardian_id, student_id),
  constraint guardian_student_links_verified_check
    check (status <> 'verified' or (verified_by is not null and verified_at is not null)),
  constraint guardian_student_links_revoked_check
    check (status <> 'revoked' or revoked_at is not null)
);

create index guardian_student_links_student_id_idx
  on public.guardian_student_links (student_id);
create index guardian_student_links_status_idx
  on public.guardian_student_links (status);

-- Only one active primary guardian per student
create unique index guardian_student_links_one_primary
  on public.guardian_student_links (student_id)
  where is_primary and status <> 'revoked';

-- ---------------------------------------------------------------
-- departments and staff_profiles
-- ---------------------------------------------------------------
create table public.departments (
  id           uuid primary key default gen_random_uuid(),
  name         text not null unique check (length(trim(name)) > 0),
  code         text unique,
  description  text,
  is_active    boolean not null default true,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create table public.staff_profiles (
  id               uuid primary key default gen_random_uuid(),
  profile_id       uuid unique references public.profiles (id) on delete restrict,
  campus_id        uuid not null references public.campuses (id) on delete restrict,
  department_id    uuid references public.departments (id) on delete restrict,
  staff_number     text not null unique check (length(trim(staff_number)) > 0),
  first_name       text not null check (length(trim(first_name)) > 0),
  last_name        text not null check (length(trim(last_name)) > 0),
  gender           text check (gender in ('female', 'male')),
  phone            text,
  email            text
                   check (email is null or email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  job_title        text,
  employment_type  text
                   check (employment_type in ('full_time', 'part_time', 'contract', 'volunteer')),
  hired_on         date,
  left_on          date,
  status           text not null default 'active'
                   check (status in ('active', 'on_leave', 'resigned', 'terminated', 'archived')),
  created_by       uuid references public.profiles (id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint staff_profiles_dates_check
    check (left_on is null or hired_on is null or left_on >= hired_on)
);

create index staff_profiles_campus_id_idx on public.staff_profiles (campus_id);
create index staff_profiles_department_id_idx on public.staff_profiles (department_id);
create index staff_profiles_status_idx on public.staff_profiles (status);
create index staff_profiles_name_idx
  on public.staff_profiles (lower(last_name), lower(first_name));

-- ---------------------------------------------------------------
-- updated_at triggers (function created in migration 0001)
-- ---------------------------------------------------------------
create trigger students_set_updated_at
  before update on public.students
  for each row execute function public.set_updated_at();

create trigger guardians_set_updated_at
  before update on public.guardians
  for each row execute function public.set_updated_at();

create trigger guardian_student_links_set_updated_at
  before update on public.guardian_student_links
  for each row execute function public.set_updated_at();

create trigger departments_set_updated_at
  before update on public.departments
  for each row execute function public.set_updated_at();

create trigger staff_profiles_set_updated_at
  before update on public.staff_profiles
  for each row execute function public.set_updated_at();

-- ---------------------------------------------------------------
-- Row Level Security: ON. No policies yet, so the browser keys
-- can read and write nothing until the policies migration (Step 8).
-- ---------------------------------------------------------------
alter table public.students                enable row level security;
alter table public.guardians               enable row level security;
alter table public.guardian_student_links  enable row level security;
alter table public.departments             enable row level security;
alter table public.staff_profiles          enable row level security;

commit;